// Generated by `just generate` from `src/plugins/claudetto/slices/statusline/width.ts`. Edit the source and run `just generate`.
// The width of text in terminal columns, and a cut to a width. A color sequence has no width.

import { ICON } from "./icons.ts";

const ESC = String.fromCharCode(27);
const SEQUENCE = new RegExp(`${ESC}\\[[0-9;]*m`, "g");
const SPLIT = new RegExp(`(${ESC}\\[[0-9;]*m)`);

export const plainText = (text: string): string => text.replace(SEQUENCE, "");

// Flat `low, high` pairs of the code points with two columns: default emoji presentation below U+10000 (a text symbol such as `✎` has one), and the East Asian wide blocks.
const WIDE = [
  0x231a, 0x231b, 0x23e9, 0x23ec, 0x23f0, 0x23f0, 0x23f3, 0x23f3, 0x25fd,
  0x25fe, 0x2614, 0x2615, 0x2648, 0x2653, 0x267f, 0x267f, 0x2693, 0x2693,
  0x26a1, 0x26a1, 0x26aa, 0x26ab, 0x26bd, 0x26be, 0x26c4, 0x26c5, 0x26ce,
  0x26ce, 0x26d4, 0x26d4, 0x26ea, 0x26ea, 0x26f2, 0x26f3, 0x26f5, 0x26f5,
  0x26fa, 0x26fa, 0x26fd, 0x26fd, 0x2705, 0x2705, 0x270a, 0x270b, 0x2728,
  0x2728, 0x274c, 0x274c, 0x274e, 0x274e, 0x2753, 0x2755, 0x2757, 0x2757,
  0x2795, 0x2797, 0x27b0, 0x27b0, 0x27bf, 0x27bf, 0x2b1b, 0x2b1c, 0x2b50,
  0x2b50, 0x2b55, 0x2b55, 0x1100, 0x115f, 0x2e80, 0xa4cf, 0xac00, 0xd7a3,
  0xf900, 0xfaff, 0xfe30, 0xfe6f, 0xff00, 0xff60, 0xffe0, 0xffe6, 0x1f300,
  0x1faff, 0x20000, 0x3fffd,
];

// Combining marks, the zero width joiner, and variation selectors.
const ZERO = [0x300, 0x36f, 0x200d, 0x200d, 0xfe00, 0xfe0f];

const inRanges = (code: number, ranges: readonly number[]): boolean =>
  ranges.some(
    (low, i) => i % 2 === 0 && code >= low && code <= (ranges[i + 1] as number),
  );

const columnsOf = (char: string): number => {
  const code = char.codePointAt(0) ?? 0;
  return inRanges(code, ZERO) ? 0 : inRanges(code, WIDE) ? 2 : 1;
};

export const width = (text: string): number =>
  [...plainText(text)].reduce((sum, char) => sum + columnsOf(char), 0);

/** `text` cut to `max` columns with `…` last. A reset closes the cut text, so no color leaks. */
export const truncate = (text: string, max: number): string => {
  if (width(text) <= max) return text;
  if (max <= 0) return "";
  let out = "";
  let columns = 0;
  let colored = false;
  for (const [index, part] of text.split(SPLIT).entries()) {
    // The odd parts are the color sequences.
    if (index % 2 === 1) {
      out += part;
      colored = part !== "\u001b[0m";
      continue;
    }
    for (const char of part) {
      columns += columnsOf(char);
      if (columns > max - 1)
        return `${out}${ICON.ellipsis}${colored ? "\u001b[0m" : ""}`;
      out += char;
    }
  }
  return out;
};
